%[text] # Build a fuselage from its CST parameters
%[text] Move a slider and the fuselage is rebuilt with `CST2Fuselage` (the second section runs again).
%[text] Kulfan (2008, Sec. VIII-IX): a body is a distribution of cross sections along `psi = x/L`. Every cross section has an upper and a lower lobe joined at the maximum half-breadth `w`: `z = zm + hU*(1 - eta^2)^NU` above and `z = zm - hL*(1 - eta^2)^NL` below, with `y = w*eta` (`N = 0.5` ellipse, `N` towards 0 rectangle, `N = 1` parabola).
%[text] Default values: an airliner-like body fitted with `Fuselage2CST(F,n=4,nz=2,nN=0)`.
%[text] ## Setup
clc; clear; close all
addpath(fullfile('..','src'))       % matlab_cst functions (run from the examples folder)

% plot settings
axFS = 13;
axFN = "Times New Roman";
lw   = 2;
axlw = 1.25;
set(0, 'defaultAxesTickLabelInterpreter','latex', ...
       'defaultTextInterpreter','latex', ...
       'DefaultLegendInterpreter','latex');
%%
%[text] ## CST parameters
% length [m] and class function exponents
L  = 40; %[control:slider:0b6d]{"position":[6,8]}
N1 = 0.5; %[control:slider:cc7f]{"position":[6,9]}
N2 = 1; %[control:slider:2e5f]{"position":[6,7]}
% upper lobe height hU/L
Ahu = zeros(5,1); Ahl = zeros(5,1); Aw = zeros(5,1); Bzm = zeros(3,1);
Ahu(1) = 0.188; %[control:slider:8fea]{"position":[10,15]}
Ahu(2) = 0.121; %[control:slider:c62d]{"position":[10,15]}
Ahu(3) = 0.039; %[control:slider:976a]{"position":[10,15]}
Ahu(4) = 0.257; %[control:slider:4656]{"position":[10,15]}
Ahu(5) = 0.232; %[control:slider:303e]{"position":[10,15]}
% lower lobe height hL/L
Ahl(1) = 0.169; %[control:slider:8400]{"position":[10,15]}
Ahl(2) = 0.109; %[control:slider:40e6]{"position":[10,15]}
Ahl(3) = 0.035; %[control:slider:a60a]{"position":[10,15]}
Ahl(4) = 0.231; %[control:slider:c301]{"position":[10,15]}
Ahl(5) = 0.208; %[control:slider:a906]{"position":[10,15]}
% half-breadth w/L
Aw(1) = 0.188; %[control:slider:30c6]{"position":[9,14]}
Aw(2) = 0.121; %[control:slider:df1b]{"position":[9,14]}
Aw(3) = 0.039; %[control:slider:3f16]{"position":[9,14]}
Aw(4) = 0.257; %[control:slider:a978]{"position":[9,14]}
Aw(5) = 0.232; %[control:slider:163c]{"position":[9,14]}
% tail values hU/L, hL/L, w/L
dzhu = 0.0047; %[control:slider:1962]{"position":[8,14]}
dzhl = 0.0042; %[control:slider:9b1c]{"position":[8,14]}
dzw  = 0.0047; %[control:slider:6c8f]{"position":[8,14]}
% max half-breadth line zm/L (nose, middle control, tail)
Bzm(1) = 0.005; %[control:slider:a7c0]{"position":[10,15]}
Bzm(2) = -0.019; %[control:slider:446d]{"position":[10,16]}
Bzm(3) = 0.026; %[control:slider:a919]{"position":[10,15]}
% lobe exponents
NU = 0.5; %[control:slider:7d6a]{"position":[6,9]}
NL = 0.5; %[control:slider:ade8]{"position":[6,9]}

% BUILD ---------------------------------------------------------------------
CST = struct('L',L,'N1',N1,'N2',N2,'Ahu',Ahu,'dzhu',dzhu,'Ahl',Ahl,'dzhl',dzhl, ...
             'Aw',Aw,'dzw',dzw,'Bzm',Bzm,'BNU',NU,'BNL',NL);
F = CST2Fuselage(CST,npsi=61);
[wmax,iw] = max(F.w);
fprintf('L = %.1f m | max width %.2f m, max height %.2f m at x = %.1f m | fineness %.1f\n', ... %[output:group:19fda75b] %[output:17944c6f]
        F.L,2*wmax,F.zc(iw) - F.zk(iw),F.x(iw),F.L/(2*wmax)); %[output:group:19fda75b] %[output:17944c6f]

% PLOT ----------------------------------------------------------------------
figure('Position',[100 100 1000 800]); %[output:0f3f84fe]
tiledlayout(2,3,'TileSpacing','compact'); %[output:0f3f84fe]
ax1 = nexttile([1 3]); %[output:0f3f84fe]
F.plot(ax1); %[output:0f3f84fe]
view(ax1,[-35 20]); axis(ax1,'off'); %[output:0f3f84fe]
ax2 = nexttile([1 2]); hold on %[output:0f3f84fe]
F.plotLines(ax2,'LineWidth',lw); %[output:0f3f84fe]
xlabel('$x$ [m]'); ylabel('$z$, $w$ [m]'); legend('Location','southoutside','NumColumns',2); %[output:0f3f84fe]
styleAx(ax2,axFS,axFN,axlw); %[output:0f3f84fe]
ax3 = nexttile; hold on %[output:0f3f84fe]
[y,z] = F.section(iw,121);
plot(ax3,y,z,'k-','LineWidth',lw); %[output:0f3f84fe]
plot(ax3,[-1 1]*F.w(iw),[1 1]*F.zm(iw),'k:'); %[output:0f3f84fe]
axis(ax3,'equal'); xlabel('$y$ [m]'); ylabel('$z$ [m]'); title('largest section'); %[output:0f3f84fe]
styleAx(ax3,axFS,axFN,axlw); %[output:0f3f84fe]
%%
%[text] ## Local functions
function styleAx(ax,axFS,axFN,axlw)
% axes style of the script skeleton
ax.FontName  = axFN;
ax.FontSize  = axFS;
ax.LineWidth = axlw;
ax.XMinorTick = "on"; ax.YMinorTick = "on";
ax.Layer = "top";
box(ax,'on'); grid(ax,'on');
ax.GridAlpha = 0.1;
end

